CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE IF NOT EXISTS cameras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, location text NOT NULL, status text NOT NULL DEFAULT 'online', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS detection_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), producer_event_id text NOT NULL, camera_id uuid NOT NULL REFERENCES cameras(id), rule text NOT NULL, severity text NOT NULL, observed_at timestamptz NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, producer_event_id));
CREATE TABLE IF NOT EXISTS incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), camera_id uuid NOT NULL REFERENCES cameras(id), rule text NOT NULL, severity text NOT NULL, status text NOT NULL DEFAULT 'open', title text NOT NULL, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, occurrences integer NOT NULL DEFAULT 1, acknowledged_at timestamptz, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS incidents_open_correlation_idx ON incidents(organization_id, camera_id, rule, status, last_seen_at DESC);
CREATE TABLE IF NOT EXISTS incident_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id), type text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), url text NOT NULL, secret text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), topic text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), last_error text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX IF NOT EXISTS outbox_jobs_ready_idx ON outbox_jobs(status, available_at);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES outbox_jobs(id), subscription_id uuid NOT NULL REFERENCES webhook_subscriptions(id), status_code integer, error text, attempted_at timestamptz NOT NULL DEFAULT now());
